#!/usr/bin/env python3
"""Generates docs/CONTRIBUTIONS.md with measured line counts per team member (re-run any time: python3 scripts/contribution_report.py)."""
import pathlib, re
root = pathlib.Path(__file__).resolve().parent.parent
members = [
 ("Saksham (Team Leader)", "OOP architecture, MedicineSystem, integration, security/authentication, app shell, user management, settings",
  ["backend/main.cpp","backend/saksham.cpp","backend/saksham_api.cpp","backend/include/json.h","backend/include/http_server.h","backend/include/static_files.h","backend/include/crypto.h","backend/include/util.h","backend/include/schema.h",
   "frontend/src/main.jsx","frontend/src/App.jsx","frontend/src/api.js","frontend/src/auth.jsx","frontend/src/ui.jsx","frontend/src/index.css","frontend/src/pages/Login.jsx","frontend/src/pages/Users.jsx","frontend/src/pages/Settings.jsx",
   "frontend/package.json","frontend/vite.config.js","frontend/tailwind.config.js","frontend/postcss.config.js","frontend/index.html","CMakeLists.txt","tests/unit_tests.cpp"]),
 ("Nikita", "Patient management, medicine requests, prescriptions, priority queue (backend + frontend)",
  ["backend/nikita.cpp","backend/nikita_api.cpp","frontend/src/pages/Patients.jsx","frontend/src/pages/Queue.jsx"]),
 ("Vansh", "Medicine catalogue, inventory, batches/expiry, restocking (backend + frontend)",
  ["backend/vansh.cpp","backend/vansh_api.cpp","frontend/src/pages/Medicines.jsx","frontend/src/pages/Inventory.jsx"]),
 ("Krishna", "Pharmacy management, availability/distance search, alternatives and substitution (backend + frontend)",
  ["backend/krishna.cpp","backend/krishna_api.cpp","frontend/src/pages/Pharmacies.jsx","frontend/src/pages/Alternatives.jsx"]),
 ("Ankit", "Smart distribution, waiting list, transactions, notifications (backend + frontend)",
  ["backend/ankit.cpp","backend/ankit_api.cpp","frontend/src/pages/Distribution.jsx","frontend/src/pages/WaitingList.jsx","frontend/src/pages/Transactions.jsx","frontend/src/pages/Notifications.jsx"]),
 ("Shaurya", "DSA, database core, demo-data seeding, analytics, dashboard, reports (backend + frontend)",
  ["backend/shaurya.cpp","backend/shaurya_api.cpp","backend/shaurya_seed.cpp","backend/seed_catalogue.h","frontend/src/pages/Dashboard.jsx","frontend/src/pages/Analytics.jsx","frontend/src/pages/charts.jsx","tests/test_database.py"]),
]
shared = ["tests/test_api.py","tests/ui/ui_test.cjs","tests/ui/build.cjs","tests/ui/shims/react-router-dom.jsx","tests/ui/shims/recharts.jsx","scripts/run_tests.sh","scripts/run_ui_tests.sh","scripts/export_schema.py","scripts/gen_api_docs.py","scripts/contribution_report.py"]
DATA = {"backend/seed_catalogue.h"}      # pure data table, reported separately from logic
def count(rel):
    lines = (root / rel).read_text(errors="ignore").splitlines()
    code = [l for l in lines if l.strip() and not re.match(r"^\s*(//|#\s|/\*|\*)", l)]
    return len(lines), len(code)
out = ["# Team contribution report", "", "Generated by `scripts/contribution_report.py`; every number below is measured from the files in this repository (total lines / non-blank, non-comment lines).",
       "Counts show where code lives, not effort or quality. Files are assigned by module ownership, and the original six-file split (`saksham.cpp` … `shaurya.cpp`) is preserved.", ""]
summary = []
for name, resp, files in members:
    out += [f"## {name}", f"**Responsibility:** {resp}", "", "| File | Total lines | Code lines |", "|---|---:|---:|"]
    tl = tc = dl = 0
    for f in files:
        t, c = count(f); out.append(f"| `{f}`{' (data table)' if f in DATA else ''} | {t} | {c} |")
        if f in DATA: dl += t
        else: tl += t; tc += c
    out += [f"| **Total (excluding data table)** | **{tl}** | **{tc}** |", ""] + ([f"Seed data table: {dl} lines (reported separately).", ""] if dl else [])
    summary.append((name, tl, tc, dl, len(files)))
out += ["## Shared files (written jointly, not attributed to one member)", "", "| File | Total lines | Code lines |", "|---|---:|---:|"]
for f in shared: t, c = count(f); out.append(f"| `{f}` | {t} | {c} |")
out += ["", "## Summary", "", "| Member | Files | Lines (excl. data) | Code lines | Data lines |", "|---|---:|---:|---:|---:|"]
for n, t, c, d, k in summary: out.append(f"| {n} | {k} | {t} | {c} | {d} |")
out += ["", "## Notes", "- Saksham's total includes shared infrastructure (JSON, HTTP server, crypto, schema) because the team leader owns the architecture.",
        "- Shaurya's data table (`seed_catalogue.h`) is a list of generic drugs and strengths, not logic, so it is excluded from the comparison.",
        "- Testing: every member's modules are exercised by the shared suites (`tests/test_api.py`, `tests/ui/ui_test.cjs`); `tests/unit_tests.cpp` and `tests/test_database.py` are attributed above.",
        "- Balance among the five non-lead members ranges from the smallest to the largest total shown above (Krishna lowest, Shaurya/Nikita highest). The difference is not adjusted artificially; adding genuine work (e.g. more tests per module) is the fair way to even it out.",
        "- Each member should be able to explain the files they own (data flow, validation, failure cases) for the PBL viva; the `Owner` column of `docs/API.md` lists which member owns each route."]
(root / "docs/CONTRIBUTIONS.md").write_text("\n".join(out) + "\n"); print("\n".join(out[-14:]))
